// The private file storage contract used by guest ID documents. Business logic depends only on this interface, so the
// local development adapter can later be swapped for a private S3-compatible adapter without changing that logic.
// Keys are generated by the server (never derived from user input or original file names) and are never shown to users.

// Injection token for the configured storage adapter.
export const FILE_STORAGE = Symbol('FILE_STORAGE');

// Allowed shape of a storage key: lower-case segments of letters, digits, and dashes separated by "/" (no dots, so no
// "..", no file extensions, and no absolute paths).
export const STORAGE_KEY_PATTERN = /^[a-z0-9][a-z0-9-]{0,63}(\/[a-z0-9][a-z0-9-]{0,63}){0,4}$/;

// Thrown when a key does not match STORAGE_KEY_PATTERN (a programming error, never caused by user input).
export class InvalidStorageKeyError extends Error {
  // Builds the error without repeating the key (keys are private).
  constructor() {
    super('Invalid storage key.');
    this.name = 'InvalidStorageKeyError';
  }
}

// Private file storage operations.
export interface FileStorage {
  /** Stores the bytes under the key (atomically: a reader never sees a half-written file). */
  put(key: string, content: Buffer): Promise<void>;
  /** Returns the stored bytes, or null when nothing is stored under the key. */
  read(key: string): Promise<Buffer | null>;
  /** Removes the stored file; removing a missing file is not an error. */
  delete(key: string): Promise<void>;
}

// Refuses keys that do not match the allowed shape.
export function assertValidKey(key: string): void {
  if (!STORAGE_KEY_PATTERN.test(key)) throw new InvalidStorageKeyError();
}
